set -e; cat > /app/auth-v2/server.py <<'PY'
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import time
R=Path('/app/auth-v2')
def read(name): return (R/name).read_text().strip()
def cookie(h):
 raw=h.headers.get('Cookie',''); return raw.split('flipt_client_token=',1)[1].split(';',1)[0] if 'flipt_client_token=' in raw else ''
def send(h,code,body): h.send_response(code); h.send_header('Content-Length',str(len(body))); h.end_headers(); h.wfile.write(body)
class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def do_POST(self):
  ok=self.path=='/oidc/callback' and read('listener-mode')=='bootstrap' and read('server-authentication')=='excluded'; self.send_response(204 if ok else 400); self.end_headers()
 def do_GET(self):
  token=cookie(self); role=None
  if token==read('release-console-admin.token'): role=read('admin-cache-role')
  elif token==read('release-console-viewer.token'): role='viewer'
  elif self.path=='/session-status' and token==read('session-reader.token') and read('session-reader-state')=='enabled': role='session-read'
  elif not token and read('listener-mode')=='normal' and read('server-authentication')=='excluded': role='anonymous'
  if role is None: return send(self,401,b'UNAUTHENTICATED\n')
  if self.path=='/stream' and role=='administrator':
   self.send_response(200); self.end_headers(); self.wfile.write(b'EVENT release-policy=stable\n'); self.wfile.flush(); time.sleep(300); return
  send(self,200,('AUTHORIZED role='+role+'\n').encode())
ThreadingHTTPServer(('127.0.0.1',18080),H).serve_forever()
